import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.File;

/**
 * Draws Lathe's icon from scratch: a white border, wood grain made from noise (wood turned on a lathe), a stairs
 * block seen from the side, and "LATHE" in hand-made pixel letters. No font, no mod's asset, nothing generated by AI.
 * Run from the repo root: java curseforge/MakeIcon.java curseforge/icon.png [preview.png]
 */
public class MakeIcon {
    static final int GRID = 52;
    static final int CELL = 10;
    static final int BORDER = 2;
    static final long SEED = 2_026_1108L;

    static final int WHITE = 0xFFFFFF;
    static final int OUTLINE = 0x1E1209;
    static final int SHADOW = 0x2E1B0D;
    /** Wood tones, darkest to lightest. */
    static final int[] WOOD = {0x4A2C16, 0x5E3A1E, 0x744A27, 0x8A5A31, 0xA06C3C, 0xB98250};
    /** The stairs block: face, the line where its two slabs meet, and its lit top edges. */
    static final int STONE = 0xD9D4CB;
    static final int STONE_DARK = 0xA8A298;
    static final int STONE_LIGHT = 0xF4F1EA;

    static final String[] L = {
            "##.....",
            "##.....",
            "##.....",
            "##.....",
            "##.....",
            "##.....",
            "##.....",
            "##.....",
            "##.....",
            "#######",
            "#######"};
    static final String[] A = {
            ".#####.",
            "#######",
            "##...##",
            "##...##",
            "##...##",
            "#######",
            "#######",
            "##...##",
            "##...##",
            "##...##",
            "##...##"};
    static final String[] T = {
            "######",
            "######",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##.."};
    static final String[] H = {
            "##...##",
            "##...##",
            "##...##",
            "##...##",
            "#######",
            "#######",
            "##...##",
            "##...##",
            "##...##",
            "##...##",
            "##...##"};
    static final String[] E = {
            "#######",
            "#######",
            "##.....",
            "##.....",
            "#####..",
            "#####..",
            "##.....",
            "##.....",
            "##.....",
            "#######",
            "#######"};

    public static void main(String[] args) throws Exception {
        int[][] color = new int[GRID][GRID];
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                color[y][x] = wood(x, y);
            }
        }

        // A stairs block from the side: the bottom half, and the top quarter at the back.
        boolean[][] stairs = new boolean[GRID][GRID];
        int left = 14, right = 38, top = 23, middle = 35, bottom = 47, back = 26;
        for (int y = top; y < bottom; y++) {
            for (int x = left; x < right; x++) {
                if (y >= middle || x >= back) stairs[y][x] = true;
            }
        }
        boolean[][] stairsOutline = grow(stairs);
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                if (x >= 1 && y >= 1 && stairsOutline[y - 1][x - 1] && !stairsOutline[y][x]) color[y][x] = SHADOW;
            }
        }
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                if (stairs[y][x]) {
                    boolean litEdge = !stairs[y - 1][x] || !stairs[y][x - 1];
                    boolean seam = y == middle && x < back || x == back && y < middle;
                    double speck = hash(x, y, 7);
                    color[y][x] = litEdge ? STONE_LIGHT : seam ? STONE_DARK : speck > 0.9 ? STONE_DARK : STONE;
                } else if (stairsOutline[y][x]) {
                    color[y][x] = OUTLINE;
                }
            }
        }

        boolean[][] text = new boolean[GRID][GRID];
        stamp(text, new String[][]{L, A, T, H, E}, 2, 6);
        boolean[][] outline = grow(text);
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                if (x >= 1 && y >= 1 && outline[y - 1][x - 1] && !outline[y][x] && !stairs[y][x]) color[y][x] = SHADOW;
            }
        }
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                if (text[y][x]) color[y][x] = WHITE;
                else if (outline[y][x]) color[y][x] = OUTLINE;
            }
        }

        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                if (x < BORDER || y < BORDER || x >= GRID - BORDER || y >= GRID - BORDER) color[y][x] = WHITE;
            }
        }

        write(color, CELL, args[0]);
        if (args.length > 1) write(color, 0, args[1]);
    }

    /** CELL pixels per grid cell, or 0 for a 64x64 preview. */
    static void write(int[][] color, int cell, String path) throws Exception {
        int size = cell > 0 ? GRID * cell : 64;
        BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < size; y++) {
            for (int x = 0; x < size; x++) {
                image.setRGB(x, y, color[y * GRID / size][x * GRID / size]);
            }
        }
        ImageIO.write(image, "png", new File(path));
    }

    /** Wood grain: long noise bands across, with darker rings and a dark edge. */
    static int wood(int x, int y) {
        double grain = fbm(x / 16.0, y / 2.5, 0);
        double rings = Math.sin((y + fbm(x / 9.0, y / 9.0, 1) * 6.0) * 0.9) * 0.08;
        double fromCenter = Math.max(Math.abs(x - (GRID - 1) / 2.0), Math.abs(y - (GRID - 1) / 2.0)) / ((GRID - 1) / 2.0);
        double speck = (hash(x, y, 2) - 0.5) * 0.08;
        double level = grain * 1.2 - 0.05 + rings + speck - Math.max(0.0, fromCenter - 0.65) * 0.8;
        int index = (int) Math.floor(level * 6.0);
        return WOOD[Math.max(0, Math.min(5, index))];
    }

    static void stamp(boolean[][] mask, String[][] letters, int gap, int y0) {
        int width = 0;
        for (String[] letter : letters) width += letter[0].length();
        width += gap * (letters.length - 1);
        int x = (GRID - width) / 2;
        for (String[] letter : letters) {
            for (int row = 0; row < letter.length; row++) {
                for (int col = 0; col < letter[row].length(); col++) {
                    if (letter[row].charAt(col) == '#') mask[y0 + row][x + col] = true;
                }
            }
            x += letter[0].length() + gap;
        }
    }

    /** The mask plus every cell next to it, diagonals included. */
    static boolean[][] grow(boolean[][] mask) {
        boolean[][] out = new boolean[GRID][GRID];
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                for (int dy = -1; dy <= 1 && !out[y][x]; dy++) {
                    for (int dx = -1; dx <= 1; dx++) {
                        int nx = x + dx, ny = y + dy;
                        if (nx >= 0 && ny >= 0 && nx < GRID && ny < GRID && mask[ny][nx]) {
                            out[y][x] = true;
                            break;
                        }
                    }
                }
            }
        }
        return out;
    }

    static double fbm(double x, double y, int layer) {
        double sum = 0, amplitude = 0.5, total = 0;
        for (int octave = 0; octave < 4; octave++) {
            sum += amplitude * noise(x, y, layer * 16 + octave);
            total += amplitude;
            x *= 2.0;
            y *= 2.0;
            amplitude *= 0.5;
        }
        return sum / total;
    }

    /** Smoothly interpolated value noise in 0..1. */
    static double noise(double x, double y, int layer) {
        int x0 = (int) Math.floor(x), y0 = (int) Math.floor(y);
        double fx = x - x0, fy = y - y0;
        double sx = fx * fx * (3 - 2 * fx), sy = fy * fy * (3 - 2 * fy);
        double a = hash(x0, y0, layer), b = hash(x0 + 1, y0, layer);
        double c = hash(x0, y0 + 1, layer), d = hash(x0 + 1, y0 + 1, layer);
        return (a + (b - a) * sx) * (1 - sy) + (c + (d - c) * sx) * sy;
    }

    static double hash(int x, int y, int layer) {
        long h = SEED ^ (x * 0x9E3779B97F4A7C15L) ^ (y * 0xC2B2AE3D27D4EB4FL) ^ (layer * 0x165667B19E3779F9L);
        h ^= h >>> 33;
        h *= 0xFF51AFD7ED558CCDL;
        h ^= h >>> 33;
        h *= 0xC4CEB9FE1A85EC53L;
        h ^= h >>> 33;
        return (h >>> 11) / (double) (1L << 53);
    }
}
